const title = $json.article_title || 'your article';
const name = $json.doctor_name || 'Doctor';
const revised = Number($json.current_version) > 1;
return { json: {
  doctor_id: $json.doctor_id,
  article_id: $json.article_id,
  campaign_id: $json.campaign_id,
  communication_type: revised ? 'DOCTOR_REVISED_DRAFT' : 'DOCTOR_REVIEW_REQUEST',
  subject: revised ? 'Your revised article is ready for review' : 'Your article is ready for review',
  message_text: ['Hello ' + name + ',', '', (revised ? 'The revised article' : 'A draft article') + ' "' + title + '" is ready for your review. Please use the secure link below to approve it or request changes.', '', 'This review link expires at the review deadline.', '', 'Apex Dental Partners'].join(String.fromCharCode(10)),
  action_url: $json.review_url,
} };
